func (r *systemConnectorRepoGorm) GetByConnectorName(ctx context.Context, connectorName string) (*model.Source, error) {
	var s model.Source
	err := r.db.WithContext(ctx).Where("connector_name = ?", connectorName).First(&s).Error
	if err != nil {
		if errors.Is(err, gorm.ErrRecordNotFound) {
			return r.loadRegistryFallback(ctx, connectorName)
		}
		return nil, err
	}
	r.enrichRegistryCredentials(ctx, &s)
	return &s, nil
}

type connectionRegistrySnapshot struct {
	EngineType  string `gorm:"column:engine_type"`
	Host        string `gorm:"column:host"`
	Port        int    `gorm:"column:port"`
	DefaultDB   string `gorm:"column:default_database"`
	OptionsJSON string `gorm:"column:options_json"`
}

func (r *systemConnectorRepoGorm) queryRegistrySnapshot(ctx context.Context, connectorName string) (connectionRegistrySnapshot, error) {
	var reg connectionRegistrySnapshot
	err := r.db.WithContext(ctx).Raw(`
		SELECT COALESCE(engine_type, '') AS engine_type,
		       COALESCE(host, '') AS host,
		       COALESCE(port, 0) AS port,
		       COALESCE(default_database, '') AS default_database,
		       COALESCE(options_json::text, '') AS options_json
		FROM cdc_system.connection_registry
		WHERE connection_code = ?
		LIMIT 1
	`, connectorName).Scan(&reg).Error
	return reg, err
}

func (r *systemConnectorRepoGorm) loadRegistryFallback(ctx context.Context, connectorName string) (*model.Source, error) {
	reg, err := r.queryRegistrySnapshot(ctx, connectorName)
	if err != nil || (reg.OptionsJSON == "" && reg.Host == "") {
		return nil, nil
	}
	s := &model.Source{
		ConnectorName:       connectorName,
		SourceType:          reg.EngineType,
		DatabaseIncludeList: reg.DefaultDB,
	}
	applyRegistrySnapshot(s, reg)
