// BuildStoredConfigBaselineSnapshot constructs a clean baseline config map from a stored DB snapshot
// (RawConfigSanitized, ServerAddress, and connection_registry OptionsJSON) and live Kafka Connect
// config, strictly filtering out any masked or sentinel values and binding URI templates to stored hosts.
func BuildStoredConfigBaselineSnapshot(fp *StoredSourceSnapshot, liveCfg map[string]string, incoming map[string]string) map[string]string {
	baseline := make(map[string]string)
	var rawMap map[string]string
	if fp != nil {
		if len(fp.RawConfigSanitized) > 0 {
			if err := json.Unmarshal(fp.RawConfigSanitized, &rawMap); err == nil {
				for k, v := range rawMap {
					if !IsKeepOrMaskedSecret(v) && !IsMaskedURI(v) {
						baseline[k] = v
					}
				}
			}
		}
		if addr := strings.TrimSpace(fp.ServerAddress); addr != "" && !IsMaskedURI(addr) {
			if fp.SourceType == "mongodb" || strings.HasPrefix(addr, "mongodb://") || strings.HasPrefix(addr, "mongodb+srv://") {
				baseline["mongodb.connection.string"] = addr
			} else if !strings.Contains(addr, "://") && (fp.SourceType == "postgresql" || fp.SourceType == "mysql") {
				parts := strings.SplitN(addr, ":", 2)
				if baseline["database.hostname"] == "" && parts[0] != "" {
					baseline["database.hostname"] = parts[0]
				}
				if len(parts) == 2 && baseline["database.port"] == "" && parts[1] != "" {
					baseline["database.port"] = parts[1]
				}
			}
		}
		if len(fp.OptionsJSON) > 0 {
			var opts map[string]string
			if err := json.Unmarshal(fp.OptionsJSON, &opts); err == nil {
				user := strings.TrimSpace(opts["username"])
				pass := opts["password"]
				uri := strings.TrimSpace(opts["uri"])
				sslmode := strings.TrimSpace(opts["sslmode"])

				if uri != "" && !IsKeepOrMaskedSecret(uri) && !IsMaskedURI(uri) {
					baseline["mongodb.connection.string"] = uri
				}
				if user != "" && !IsKeepOrMaskedSecret(user) {
					if baseline["database.user"] == "" {
						baseline["database.user"] = user
					}
					if baseline["sftp.username"] == "" {
						baseline["sftp.username"] = user
					}
				}
				if pass != "" && !IsKeepOrMaskedSecret(pass) {
					baseline["database.password"] = pass
					baseline["mongodb.password"] = pass
					baseline["sftp.password"] = pass
				}
				if sslmode != "" && baseline["database.sslmode"] == "" {
					baseline["database.sslmode"] = sslmode
				}
				if user != "" && !IsKeepOrMaskedSecret(user) {
					credTemplate := "sftp://" + user + "@localhost/"
					if !IsKeepOrMaskedSecret(pass) && pass != "" {
						credTemplate = "sftp://" + user + ":" + pass + "@localhost/"
					}
					storedFS := strings.TrimSpace(rawMap["fs.uris"])
					if storedFS == "" && fp.ServerAddress != "" && !strings.Contains(fp.ServerAddress, "://") {
						storedFS = "sftp://***:***@" + strings.TrimSpace(fp.ServerAddress) + "/"
					}
					if storedFS != "" {
						restoredFS := RestoreMaskedURI(storedFS, credTemplate)
						if !IsMaskedURI(restoredFS) {
							baseline["fs.uris"] = restoredFS
						}
					}
					if baseline["mongodb.connection.string"] == "" {
						storedMongo := strings.TrimSpace(rawMap["mongodb.connection.string"])
						if storedMongo == "" && strings.HasPrefix(strings.TrimSpace(fp.ServerAddress), "mongodb") {
							storedMongo = strings.TrimSpace(fp.ServerAddress)
						}
						if storedMongo != "" && IsMaskedURI(storedMongo) {
							mongoTemplate := "mongodb://" + user + "@localhost/"
							if pass != "" && !IsKeepOrMaskedSecret(pass) {
								mongoTemplate = "mongodb://" + user + ":" + pass + "@localhost/"
							}
							restoredMongo := RestoreMaskedURI(storedMongo, mongoTemplate)
							if !IsMaskedURI(restoredMongo) {
								baseline["mongodb.connection.string"] = restoredMongo
							}
						}
					}
				}
			}
		}
	}
	for k, v := range liveCfg {
		if !IsKeepOrMaskedSecret(v) && !IsMaskedURI(v) {
			baseline[k] = v
		}
	}
	return baseline
}

// ValidateNoMaskedSecrets is a fail-closed guard that rejects any configuration map
// that still contains masked secrets (***, __KEEP__), masked URIs (***:***), or
// missing required database credentials before calling Kafka Connect.
func ValidateNoMaskedSecrets(cfg map[string]string) error {
	if len(cfg) == 0 {
		return errors.New("config required")
	}
	for k, v := range cfg {
		if IsKeepOrMaskedSecret(v) {
			return fmt.Errorf("config key %q contains unresolved masked secret; please enter the password", k)
		}
		if IsMaskedURI(v) {
			return fmt.Errorf("config key %q contains masked credentials in URI; please enter the full URI with credentials", k)
		}
	}
	cls := cfg["connector.class"]
	if strings.Contains(cls, "PostgresConnector") || strings.Contains(cls, "MySqlConnector") || strings.Contains(cls, "SqlServerConnector") {
		if strings.TrimSpace(cfg["database.password"]) == "" {
			return errors.New("database.password is required and could not be recovered; please enter the password")
		}
	}
	return nil
}

