// MaskURIUserInfo masks user:password in a URI or comma-separated URI list to ***:***
// (or *** when no password separator is present) so ServerAddress is safe for HTTP responses.
func MaskURIUserInfo(raw string) string {
	trimmed := strings.TrimSpace(raw)
	if trimmed == "" || !strings.Contains(trimmed, "://") {
		return raw
	}
	parts := strings.Split(trimmed, ",")
	changed := false
	for i, part := range parts {
		item := strings.TrimSpace(part)
		idx := strings.Index(item, "://")
		if idx < 0 {
			continue
		}
		scheme := item[:idx+3]
		rest := item[idx+3:]
		pathIdx := strings.IndexAny(rest, "/?")
		authority := rest
		pathQuery := ""
		if pathIdx >= 0 {
			authority = rest[:pathIdx]
			pathQuery = rest[pathIdx:]
		}
		atIdx := strings.LastIndex(authority, "@")
		if atIdx < 0 || authority[:atIdx] == "" {
			continue
		}
		userInfo := authority[:atIdx]
		hostPort := authority[atIdx+1:]
		mask := "***"
		if strings.Contains(userInfo, ":") {
			mask = "***:***"
		}
		parts[i] = scheme + mask + "@" + hostPort + pathQuery
		changed = true
	}
	if !changed {
		return raw
	}
	return strings.Join(parts, ",")
}

